    "kotlin_example": "# 1-namuna — if / else if / else bilan baholash tizimi\n\nfun main() {\n    print(\"Ballni kiriting (0-100): \")\n    val ball = readLine()!!.toInt()\n\n    if (ball >= 90) {\n        println(\"Baho: A'lo\")\n    } else if (ball >= 70) {\n        println(\"Baho: Yaxshi\")\n    } else if (ball >= 50) {\n        println(\"Baho: Qoniqarli\")\n    } else {\n        println(\"Baho: Qoniqarsiz\")\n    }\n}\n\n\n# ────────────────────────────────────────\n\n# 2-namuna — when bilan hafta kunini aniqlash (switch'ning Kotlin analogi)\n\nfun main() {\n    print(\"Kun raqamini kiriting (1-7): \")\n    val kun = readLine()!!.toInt()\n\n    when (kun) {\n        1 -> println(\"Dushanba\")\n        2 -> println(\"Seshanba\")\n        3 -> println(\"Chorshanba\")\n        4 -> println(\"Payshanba\")\n        5 -> println(\"Juma\")\n        6 -> println(\"Shanba\")\n        7 -> println(\"Yakshanba\")\n        else -> println(\"Noto'g'ri kun raqami!\")\n    }\n}\n\n\n# ────────────────────────────────────────\n\n# 3-namuna — Ternar ifoda o'rnini bosuvchi if-ifoda va mantiqiy operatorlar\n\nfun main() {\n    val yosh = 20\n    val guvohnomaBor = true\n\n    val holat = if (yosh >= 18) \"Voyaga yetgan\" else \"Voyaga yetmagan\"\n    println(\"Holat: $holat\")\n\n    if (yosh >= 18 && guvohnomaBor) {\n        println(\"Mashina haydashga ruxsat bor\")\n    } else {\n        println(\"Ruxsat yo'q\")\n    }\n\n    val kun = 6\n    if (kun == 6 || kun == 7) {\n        println(\"Bugun dam olish kuni!\")\n    } else {\n        println(\"Bugun ish kuni.\")\n    }\n}\n\n\n# ────────────────────────────────────────\n\n# 4-namuna — if-else if zanjirini when'ga qayta yozish\n\nfun main() {\n    val baho = 4\n\n    print(\"if-else if bilan: \")\n    if (baho == 5) println(\"A'lo\")\n    else if (baho == 4) println(\"Yaxshi\")\n    else if (baho == 3) println(\"Qoniqarli\")\n    else println(\"Qoniqarsiz\")\n\n    print(\"when bilan (bir xil natija): \")\n    when (baho) {\n        5 -> println(\"A'lo\")\n        4 -> println(\"Yaxshi\")\n        3 -> println(\"Qoniqarli\")\n        else -> println(\"Qoniqarsiz\")\n    }\n}\n\n\n# ────────────────────────────────────────\n\n# 5-namuna — Uchta sonni solishtirib, eng kattasini topish\n\nfun main() {\n    print(\"Uchta son kiriting: \")\n    val (a, b, c) = readLine()!!.trim().split(\" \").map { it.toInt() }\n\n    val engKatta = when {\n        a >= b && a >= c -> a\n        b >= a && b >= c -> b\n        else -> c\n    }\n\n    println(\"Eng katta: $engKatta\")\n    println(\"Tekshirish (maxOf): ${maxOf(a, b, c)}\")\n}\n\n\n# ────────────────────────────────────────\n\n# 6-namuna — Toq/juft va musbat/manfiylikni mantiqiy operatorlar bilan birlashtirish\n\nfun main() {\n    print(\"Son kiriting: \")\n    val son = readLine()!!.toInt()\n\n    val juft = (son % 2 == 0)\n    val musbat = (son > 0)\n\n    when {\n        juft && musbat -> println(\"Musbat juft son\")\n        !juft && musbat -> println(\"Musbat toq son\")\n        juft && !musbat -> println(\"Manfiy juft son (yoki nol)\")\n        else -> println(\"Manfiy toq son\")\n    }\n}"
